package com.vandorlabs.neoforge.gear;

import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.*;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;

/** Real item placement and world ticks, asynchronous native ownership, inventory preservation and saved-process reload. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearPayloadWorldChecks {
    private record Case(BlockPos root,Direction mount,NativeGearDefinition kind,int height,boolean chest){BlockPos source(){return root.relative(mount,height);}BlockPos active(){return root.relative(mount,1);}}
    private static final List<Case> CASES=new ArrayList<>();private static Actor actor;private static ServerLevel world;private static int stage,ticks,checks,pending;private static boolean running;
    private static String phase(){return System.getProperty("vandorlabs.gearJournalPhase","");}
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,2211210),"NativeGearPayload"));}}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native gear payload phase="+phase()+" stage="+stage+" tick="+ticks+": "+why);}
    private static NativeGearEntity tile(Case scene){var tile=NativeGearFormation.at(world,scene.root);need(tile!=null&&!tile.inert(),"healthy exact root "+scene.root);return tile;}
    private static int contents(CompoundTag tag){int count=0;for(var raw:tag.getList("Items",Tag.TAG_COMPOUND)){var item=(CompoundTag)raw;if(item.getString("id").equals("minecraft:diamond"))count+=item.contains("count",Tag.TAG_INT)?item.getInt("count"):item.getByte("Count");}return count;}
    private static int nativeContents(BlockPos pos){return world.getBlockEntity(pos) instanceof ChestBlockEntity chest?chest.getItem(0).getCount():0;}
    private static void unique(Case scene){var tile=tile(scene);var payload=tile.payload();if(scene.chest){int captured=payload!=null&&!payload.materialized()?contents(payload.cells().getFirst().tile()):0;int nativeCount=nativeContents(scene.source())+nativeContents(scene.active());need(captured+nativeCount==7,"exactly one seven-diamond owner captured="+captured+" native="+nativeCount+" pos="+scene.root+" phase="+tile.progress()+" error="+tile.error());if(payload!=null)need(payload.cells().getFirst().tile().getCompound("NeoForgeData").getByteArray("NativeGearOpaque").length==512,"opaque captured tile data");}else{int nativeCount=(world.getBlockState(scene.source()).is(Blocks.DIAMOND_BLOCK)?1:0)+(world.getBlockState(scene.active()).is(Blocks.DIAMOND_BLOCK)?1:0);int captured=payload!=null&&!payload.materialized()?payload.size():0;need(nativeCount+captured==1,"exactly one solid payload owner "+scene.root);}}
    private static void click(Case scene){actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);actor.setPos(scene.root.getX()+.5,scene.root.getY()+1,scene.root.getZ()-3);var hit=new BlockHitResult(Vec3.atCenterOf(scene.root).add(0,0,-.5),Direction.NORTH,scene.root,false);need(actor.gameMode.useItemOn(actor,world,ItemStack.EMPTY,InteractionHand.MAIN_HAND,hit).consumesAction(),"actual manual activation packet path "+scene.root);}
    private static void cases(){CASES.clear();int index=0;for(Direction mount:Direction.values())for(var kind:new NativeGearDefinition[]{NativeGearDefinition.EXTENDER,NativeGearDefinition.LARGE_EXTENDER})for(int height:new int[]{2,3}){int n=index++;int x=16000+n%8*48+(mount==Direction.EAST?15:mount==Direction.WEST?16:8);CASES.add(new Case(new BlockPos(x,100,16000+n/8*48),mount,kind,height,height==3));}}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(!phase().equals("roundtrip")&&!phase().equals("reload"))return;try{world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);cases();for(var scene:CASES)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){int cx=(scene.root.getX()>>4)+x,cz=(scene.root.getZ()>>4)+z;world.setChunkForced(cx,cz,true);world.getChunk(cx,cz);}if(phase().equals("reload")){for(var scene:CASES){var tile=tile(scene);need(tile.progress()==1&&tile.target()&&!tile.blocked(),"saved native rest endpoint "+scene.root+" error="+tile.error());need(tile.payload()!=null&&tile.payload().materialized(),"saved native-ownership header");need(NativeGearFormation.at(world,scene.active())!=null&&scene.root.equals(NativeGearFormation.at(world,scene.active()).owner())&&NativeGearFormation.at(world,scene.active()).mount()==scene.mount,"saved displaced section is native and correctly owned");need(tile.saveWithoutMetadata(world.registryAccess()).getByteArray("NativeGearRootOpaque").length==512,"opaque controller survives source/native journal and reload");unique(scene);}finish("reload");return;}
        for(var scene:CASES){for(int x=-5;x<=5;x++)for(int y=-5;y<=7;y++)for(int z=-5;z<=5;z++)world.setBlock(scene.root.offset(x,y,z),Blocks.AIR.defaultBlockState(),18);for(int x=-5;x<=5;x++)for(int z=-5;z<=5;z++)world.setBlock(new BlockPos(scene.root.getX()+x,95,scene.root.getZ()+z),Blocks.STONE.defaultBlockState(),3);world.setBlock(scene.root.relative(scene.mount.getOpposite()),Blocks.STONE.defaultBlockState(),3);actor.setPos(scene.root.getX()+.5,101,scene.root.getZ()-3);var stack=new ItemStack(NativeGearBindings.ITEMS.get(scene.kind.id),scene.height);actor.setItemInHand(InteractionHand.MAIN_HAND,stack);for(int part=0;part<scene.height;part++){BlockPos cell=scene.root.relative(scene.mount,part),support=cell.relative(scene.mount.getOpposite());need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(Vec3.atLowerCornerOf(scene.mount.getNormal()).scale(.5)),scene.mount,support,false)).consumesAction(),"real supported Survival placement");}need(stack.isEmpty(),"one consumed arm per placed source section");}stage=0;running=true;
        }catch(Throwable failure){failure(failure);}}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<1800,"timeout first="+tile(CASES.getFirst()).error()+" phase="+tile(CASES.getFirst()).progress());if(stage==0){for(var scene:CASES)if(!tile(scene).controller()||tile(scene).assembly().columnHeight()!=scene.height)return;for(var scene:CASES){world.setBlock(scene.source(),scene.chest?Blocks.CHEST.defaultBlockState():Blocks.DIAMOND_BLOCK.defaultBlockState(),3);if(scene.chest){var chest=(ChestBlockEntity)world.getBlockEntity(scene.source());chest.setItem(0,new ItemStack(Items.DIAMOND,7));chest.getPersistentData().putByteArray("NativeGearOpaque",new byte[512]);chest.setChanged();}var root=tile(scene);var tag=root.saveWithoutMetadata(world.registryAccess());tag.putByteArray("NativeGearRootOpaque",new byte[512]);root.loadWithComponents(tag,world.registryAccess());root.authorize(actor);root.setChanged();unique(scene);}event.getServer().saveEverything(true,true,true);for(var scene:CASES)click(scene);stage=1;return;}
        if(stage==1){boolean complete=true;for(var scene:CASES){var root=tile(scene);NativeGearPayloadTraceChecks.verify(root);need(!root.blocked(),"asynchronous preparation is not refused "+scene.root+" error="+root.error());unique(scene);if(NativeGearJournal.busy(root)&&root.progress()==1)pending++;if(root.progress()!=0||root.payload()==null||!root.payload().materialized()||NativeGearJournal.busy(root))complete=false;}if(!complete)return;need(pending>0,"actual asynchronous preparation observed");for(var scene:CASES){need(world.getBlockState(scene.source()).isAir()&&tile(scene).hasStoredSections(),"source vacated and displaced source section owned separately");if(scene.chest)need(nativeContents(scene.active())==7,"native active Chest inventory owns diamonds");click(scene);}stage=2;return;}
        if(stage==2){for(var scene:CASES){var root=tile(scene);need(!root.blocked(),"native endpoint recapture/reversal refused "+scene.root+" error="+root.error());unique(scene);if(root.progress()!=1||root.payload()==null||!root.payload().materialized()||NativeGearJournal.busy(root))return;}for(var scene:CASES)need(NativeGearFormation.at(world,scene.active())!=null&&scene.root.equals(NativeGearFormation.at(world,scene.active()).owner())&&NativeGearFormation.at(world,scene.active()).mount()==scene.mount,"displaced source section restored with exact controller/mount");finish("roundtrip");}
        }catch(Throwable failure){failure(failure);}}
    private static void finish(String marker){running=false;NativeGearJournal.testFault=null;NativeGearJournal.testPause=null;System.out.println("[vandorlabs][gear-payload] "+marker+" PASS checks="+checks+" assemblies24/sixFaces/regularLarge/heights2and3/realPlacement/manualActivation/asyncPreparation/nativeEndpoints/7diamondChest/opaqueData/reversal/reload pending="+pending);world.getServer().saveEverything(true,true,true);world.getServer().halt(false);}
    private static void failure(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][gear-payload] "+phase()+" FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
